1343	\begin{theorem}[Residue degree one over an algebraically closed base]
1344	  \label{thm:adelic_residue_degree_one}
1345	  \leanok
1346	  \lean{AlgebraicGeometry.Adelic.residueDeg_eq_one_of_isAlgClosed_curve}
1347	  \uses{def:adelic_residue_degree}
1348	  Let \(C\) be a smooth curve over an algebraically closed field \(k\). Then
1349	  every prime divisor \(P\) of \(C\) satisfies
1350	  \[
1351	    \deg P = [\kappa(P):k] = 1 .
1352	  \]
1353	\end{theorem}
1354	\begin{proof}
1355	  \leanok
1356	  \uses{def:adelic_residue_degree}
1357	  A prime divisor of \(C\) is a closed point, and \(C\) is locally of finite
1358	  type over \(k\) because it is smooth. The underlying space of a scheme
1359	  locally of finite type over a field is a Jacobson space, so
1360	  \(\kappa(P)\) is an algebraic extension of \(k\) by Zariski's lemma; since
1361	  \(k\) is algebraically closed, the structure map \(k \to \kappa(P)\) is an
1362	  isomorphism, giving \(\dim_k \kappa(P) = 1\).
1363	\end{proof}
