1390	    \mathfrak G_P^{\ge0}/\mathfrak G_P^{\ge1}\simeq_k\kappa(P).
1391	  \]
1392	  In particular \(\deg_P^{\mathrm{val}}=[\kappa(P):k]=\deg P\).
1393	\end{lemma}
1394	\begin{proof}
